-- 2. PERIOD CONFIGURATION TABLE
CREATE TABLE IF NOT EXISTS public.period_config (
    id TEXT PRIMARY KEY DEFAULT 'config',
    active_month TEXT NOT NULL,
    entered_january BOOLEAN NOT NULL DEFAULT false,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);
ALTER TABLE public.period_config ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public access period_config" ON public.period_config;
CREATE POLICY "Public access period_config" ON public.period_config FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

ON CONFLICT (id) DO UPDATE SET active_month = EXCLUDED.active_month, entered_january = EXCLUDED.entered_january, updated_at = now();

-- 3. MONTHS TABLE (12 Periods: APR 2026 to MAR 2027)
CREATE TABLE IF NOT EXISTS public.months (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    order_idx INT NOT NULL
);
ALTER TABLE public.months ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public access months" ON public.months;
CREATE POLICY "Public access months" ON public.months FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);


